using System.Collections.Generic;

namespace QuickEditer.Models
{
    public class ProjectTemplate
    {
        public string Id { get; set; } = "";
        public string Name { get; set; } = "";
        public string Description { get; set; } = "";
        public string Code { get; set; } = "";

        public static List<ProjectTemplate> BuiltIn { get; } = new()
        {
            new ProjectTemplate
            {
                Id = "blank",
                Name = "空白项目",
                Description = "最小 setup/loop 结构",
                Code = @"// {projectName}
// Generated by QuickEditer

void setup() {
  Serial.begin(115200);
  Serial.println(""{projectName} started"");
}

void loop() {
  // TODO: 在这里编写你的代码
  delay(1000);
}
"
            },
            new ProjectTemplate
            {
                Id = "blink",
                Name = "Blink 闪烁 LED",
                Description = "板载 LED 每隔 1 秒闪烁",
                Code = @"// {projectName}
// Blink 示例

#define LED_PIN 2

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  delay(1000);
  digitalWrite(LED_PIN, LOW);
  delay(1000);
}
"
            },
            new ProjectTemplate
            {
                Id = "serial",
                Name = "串口打印",
                Description = "每秒通过串口输出计数",
                Code = @"// {projectName}
// 串口打印示例

int counter = 0;

void setup() {
  Serial.begin(115200);
}

void loop() {
  Serial.print(""Counter: "");
  Serial.println(counter++);
  delay(1000);
}
"
            },
            new ProjectTemplate
            {
                Id = "wifi",
                Name = "WiFi 连接（ESP）",
                Description = "ESP32/ESP8266 连接 WiFi 并打印 IP",
                Code = @"// {projectName}
// WiFi 连接示例（ESP32/ESP8266）

#include <WiFi.h>

const char* SSID = ""your-ssid"";
const char* PASSWORD = ""your-password"";

void setup() {
  Serial.begin(115200);
  WiFi.begin(SSID, PASSWORD);

  Serial.print(""Connecting to WiFi"");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(""."");
  }

  Serial.println();
  Serial.print(""Connected, IP: "");
  Serial.println(WiFi.localIP());
}

void loop() {
  delay(1000);
}
"
            }
        };
    }
}